<script setup>
import { Link, router } from '@inertiajs/vue3';
import { reactive } from 'vue';
import AdminLayout from '../../../Layouts/AdminLayout.vue';
const props=defineProps({articles:Object,search:String,status:String});
const filters=reactive({q:props.search||'',status:props.status||''});
function filter(){router.get('/admin/articles',filters,{preserveState:true,replace:true});}
function publish(item){router.post(`/admin/articles/${item.id}/${item.status==='published'?'unpublish':'publish'}`);}
</script>
<template><AdminLayout title="精读文章" section="内容管理 / 精读文章" description="管理文章正文、解析、重点词汇、阅读理解题与发布状态。"><template #actions><Link class="btn" href="/admin/articles/create"><el-button type="primary">＋ 新建文章</el-button></Link></template>
  <section class="card"><form class="filter-bar" @submit.prevent="filter"><el-input v-model="filters.q" class="search" clearable placeholder="搜索中英文标题" @keyup.enter="filter"/><el-select v-model="filters.status"><el-option label="全部状态" value=""/><el-option label="草稿" value="draft"/><el-option label="已发布" value="published"/></el-select><el-button type="primary" native-type="submit">筛选</el-button><el-button v-if="filters.q||filters.status" text type="primary" @click="filters.q='';filters.status='';filter()">清空</el-button></form>
  <div v-if="!articles.data.length" class="empty-state"><strong>{{ filters.q||filters.status?'没有匹配的文章':'还没有文章' }}</strong><span>{{ filters.q||filters.status?'试试其他搜索词或状态':'从新建文章开始添加内容' }}</span></div>
  <div v-else class="table-wrap"><el-table :data="articles.data" stripe><el-table-column label="ID" width="80"><template #default="scope"><span class="badge-id">#{{scope.row.id}}</span></template></el-table-column><el-table-column label="文章标题" min-width="250"><template #default="scope"><div class="table-primary">{{scope.row.translation||scope.row.title}}</div><div v-if="scope.row.translation" class="table-secondary">{{scope.row.title}}</div></template></el-table-column><el-table-column prop="level" label="级别" width="110"><template #default="scope">{{scope.row.level||'—'}}</template></el-table-column><el-table-column label="状态" width="110"><template #default="scope"><el-tag :type="scope.row.status==='published'?'success':'info'" effect="light">{{scope.row.status==='published'?'已发布':'草稿'}}</el-tag></template></el-table-column><el-table-column label="最后更新" min-width="160"><template #default="scope">{{scope.row.updated_at||'—'}}</template></el-table-column><el-table-column label="操作" width="170" fixed="right"><template #default="scope"><div class="table-actions"><Link :href="`/admin/articles/${scope.row.id}/edit`"><el-button link type="primary">编辑</el-button></Link><el-button size="small" :type="scope.row.status==='published'?'danger':'primary'" :plain="scope.row.status==='published'" @click="publish(scope.row)">{{scope.row.status==='published'?'下架':'发布'}}</el-button></div></template></el-table-column></el-table></div>
  <div v-if="articles.data.length" class="table-footer"><span>共 {{ articles.total }} 篇</span><el-pagination background layout="prev, pager, next" :current-page="articles.current_page" :page-count="articles.last_page" @current-change="page=>router.get('/admin/articles',{...filters,page},{preserveState:true,replace:true})"/></div>
  </section>
</AdminLayout></template>
